import json, sys
request_id = None
initialized = False
while True:
    line = sys.stdin.readline()
    if not line:
        break
    line = line.strip()
    if not line:
        continue
    message = json.loads(line)
    if message.get('method') == 'initialize':
        request_id = message['id']
        response = {
            'jsonrpc': '2.0',
            'id': request_id,
            'result': {
                'protocolVersion': '2024-11-05',
                'capabilities': {'tools': {}},
                'serverInfo': {'name': 'demo-time-server', 'version': '1.0.0'}
            }
        }
        sys.stdout.write(json.dumps(response) + '\n')
        sys.stdout.flush()
    elif message.get('method') == 'notifications/initialized':
        initialized = True
    elif message.get('method') == 'tools/list':
        response = {
            'jsonrpc': '2.0',
            'id': message['id'],
            'result': {
                'tools': [
                    {
                        'name': 'current_time',
                        'description': '返回当前 UTC 时间和简单说明',
                        'inputSchema': {
                            'type': 'object',
                            'properties': {
                                'city': {'type': 'string', 'description': '可选城市名称'}
                            }
                        }
                    }
                ]
            }
        }
        sys.stdout.write(json.dumps(response) + '\n')
        sys.stdout.flush()
    elif message.get('method') == 'tools/call':
        args = message.get('params', {}).get('arguments', {})
        city = args.get('city', '未知城市')
        from datetime import datetime, timezone
        now = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        response = {
            'jsonrpc': '2.0',
            'id': message['id'],
            'result': {
                'content': [
                    {
                        'type': 'text',
                        'text': f'当前 UTC 时间是 {now}。如果你正在查询 {city}，请自行换算到当地时区。'
                    }
                ]
            }
        }
        sys.stdout.write(json.dumps(response) + '\n')
        sys.stdout.flush()
